#define MYVENDOR_DWT_CYCCNT (*(volatile uint32_t *)0xe0001004u)
#define MYVENDOR_DEMCR      (*(volatile uint32_t *)0xe000edfcu)
#define MYVENDOR_DEMCR_TRCENA      (1u << 24)
